def sc(ps=(),segs=(),**kw):return dict(label=kw.pop('label','Условие'),points=list(ps),segments=[list(x) for x in segs],**kw)
def tri(a='A',b='B',c='C'):return [[a,b],[b,c],[c,a]]
def eq(a,b,k=1):return dict(a=a,b=b,marks=k)
def rt(a,o,b):return dict(a=a,vertex=o,b=b)
def arc(o,a,b,k=0,r=6):return dict(vertex=o,**{'from':a,'to':b},marks=k,radius=r)
def ck(t,**kw):return dict(type=t,**kw)
def equal(*pairs):return ck('equalLength',segments=[list(x) for x in pairs])
def par(a,b,c,d):return ck('parallel',segments=[[a,b],[c,d]])
def perp(a,b,c,d):return ck('perpendicular',segments=[[a,b],[c,d]])
def col(*ps):return ck('collinear',points=list(ps))
def ang(a,o,b,d):return ck('angle',points=[a,o,b],degrees=d)
def ratio(a,b,c,d,r):return ck('distanceRatio',segments=[[a,b],[c,d]],ratio=r)
def row(q,e,r,refs):return (q,e,r,refs)
def mid(a,b):return [(a[i]+b[i])/2 for i in (0,1)]
def refl(a,o):return [2*o[i]-a[i] for i in (0,1)]
def polar(o,t,r):return [o[0]+r*math.cos(math.radians(t)),o[1]+r*math.sin(math.radians(t))]
def dist(a,b):return math.hypot(a[0]-b[0],a[1]-b[1])
def foot(p,a,b):
 u=[b[i]-a[i] for i in (0,1)];t=sum((p[i]-a[i])*u[i] for i in (0,1))/sum(x*x for x in u)
 return [a[i]+t*u[i] for i in (0,1)]
def inter(a,b,c,d):
 u=[b[i]-a[i] for i in (0,1)];v=[d[i]-c[i] for i in (0,1)];den=u[0]*v[1]-u[1]*v[0]
 t=((c[0]-a[0])*v[1]-(c[1]-a[1])*v[0])/den
 return [a[i]+t*u[i] for i in (0,1)]
def incenter(a,b,c):
 x,y,z=dist(b,c),dist(a,c),dist(a,b)
 return [(x*a[i]+y*b[i]+z*c[i])/(x+y+z) for i in (0,1)]
def asa(a,b,c=6):
 A=[0,0];B=[c,0];C=inter(A,polar(A,a,1),B,polar(B,180-b,1));return dict(A=A,B=B,C=C)
def sss(ab,ac,bc):
 x=(ac*ac+ab*ab-bc*bc)/(2*ab);return dict(A=[0,0],B=[ab,0],C=[x,math.sqrt(ac*ac-x*x)])
def case(v,label,unlock=1):return {**deepcopy(v),'label':label,'availableFromStep':unlock}
def more(v,ps=(),segs=(),**kw):
 z=deepcopy(v);z['points']=list(dict.fromkeys(z.get('points',[])+list(ps)));z['segments']=z.get('segments',[])+[list(x) for x in segs];z.update(kw);return z

def normalize(points,views):
 allp=list(points.values())
 for v in views:
  for c in v.get('circles',[]):
   o=points[c['center']];r=dist(o,points[c['through']]);allp += [[o[0]-r,o[1]-r],[o[0]+r,o[1]+r]]
 xs=[p[0] for p in allp];ys=[p[1] for p in allp];s=min(72/(max(xs)-min(xs) or 1),46/(max(ys)-min(ys) or 1))
 cx=(max(xs)+min(xs))/2;cy=(max(ys)+min(ys))/2
 return {n:[round(50+(p[0]-cx)*s,9),round(35+(p[1]-cy)*s,9),0] for n,p in points.items()}

def givens(p,pairs):
 # Separate input-length diagram. The construction uses the same scale.
 p=deepcopy(p);ps=[];segs=[]
 for i,(a,b) in enumerate(pairs,1):
  u,v=f'P{i}',f'Q{i}';p[u]=[0,2.2*(i-1)];p[v]=[dist(p[a],p[b]),2.2*(i-1)];ps +=[u,v];segs.append([u,v])
 return p,sc(ps,segs)

def add(n,part,condition,answer,rows,p,neutral,views=None,checks=(),cases=(),labels=None,offsets=None,notes=(),label_only=()):
 page=104 if n<=362 else 105 if n<=368 else 106 if n<=373 else 110 if n<=382 else 111
 EX.setdefault(n,dict(number=n,printedPages=[page],pdfPages=[page+1],parts=[],notes=[]))['parts'].append(dict(part=part,conditionSummary=condition,answer=answer,steps=[r[1] for r in rows],sourceVerified=True,mathVerified=True,visual=dict(initial='Только данные условия; новые построения открываются по шагам.',stepChanges=['Данные, дополнительные линии и выводы показаны последовательно.'],cases=[v['label'] for v in cases])))
 EX[n]['notes'].extend(notes)
 seq=views or [neutral]*len(rows);assert len(seq)==len(rows),(n,part,len(seq),len(rows))
 vv={'neutral':deepcopy(neutral)};vv.update({f'step-{i}':{**deepcopy(v),'label':f'Шаг {i}'} for i,v in enumerate(seq,1)});vv.update({f'case-{i}':deepcopy(v) for i,v in enumerate(cases,1)})
 m=dict(points=normalize(p,list(vv.values())),edges=[],planar=True,bounds=[0,0,100,70],views=vv,checks=list(checks),description=f'Задача {n}'+('' if part=='single' else f' ({part})')+': собственный чертёж. Обоснования и вычисления находятся рядом.')
 m['labels']={f'{a}{i}':f'{a}{str(i).translate(str.maketrans("0123456789","₀₁₂₃₄₅₆₇₈₉"))}' for a in ['P','Q','A','B','C','M','H'] for i in range(1,4) if f'{a}{i}' in p}
 if labels:m['labels'].update(labels)
 if offsets:m['labelOffsets']={k:v for k,v in offsets.items() if k in p}
 if label_only:m['labelOnly']=list(label_only)
 MODELS.append(dict(chapter=5,collection='main',number=n,part=part,model=m,didactics=dict(steps=[dict(prompt=r[0],justification=r[2],theoryPoints=r[3]) for r in rows])))


def circle(o,t): return dict(center=o,through=t)
def circumcenter(a,b,c):
 m=mid(a,b);n=mid(a,c)
 u=[m[0]-(b[1]-a[1]),m[1]+b[0]-a[0]];v=[n[0]-(c[1]-a[1]),n[1]+c[0]-a[0]]
 return inter(m,u,n,v)
def length_input(p,items):
 p=deepcopy(p);ps=[];ss=[]
 for i,(a,b,length) in enumerate(items):p[a]=[0,1.8*i];p[b]=[length,1.8*i];ps += [a,b];ss.append([a,b])
 return p,sc(ps,ss)
def reflected(p,a,b):return refl(p,foot(p,a,b))
def symchecks(p,a,b,p1,h):return [col(p,h,p1),equal((p,h),(h,p1)),perp(p,p1,a,b)]

