#364–365: three requested triangle types, each in its own view.
def centered_triangle(p,prefix,height,incircle=False):
 names={k:prefix+k for k in ['A','B','C','O','M','N','U','V','H','K','J']}
 q={'A':[-2,0],'B':[2,0],'C':[0,height]};q['O']=(incenter if incircle else circumcenter)(q['A'],q['B'],q['C']);q['M']=mid(q['A'],q['B']);q['N']=mid(q['A'],q['C']);q['U']=[0,4];q['V']=[q['N'][0]-height,q['N'][1]+2]
 q['H']=foot(q['O'],q['A'],q['B']);q['K']=foot(q['O'],q['A'],q['C']);q['J']=foot(q['O'],q['B'],q['C']);p.update({names[k]:v for k,v in q.items()})
 A,B,C,O,M,N,U,V,H,K,J=[names[k] for k in ['A','B','C','O','M','N','U','V','H','K','J']]
 v0=sc([A,B,C],tri(A,B,C));v1=more(v0,[],[[A,O],[B,O]]) if incircle else more(v0,[M,N],lines=[[M,U],[N,V]],rightAngles=[rt(A,M,U),rt(A,N,V)])
 vf=more(v0,[O],circles=[circle(O,H if incircle else A)])
 if incircle:vf=more(vf,[H,K,J],[[O,H],[O,K],[O,J]],rightAngles=[rt(O,H,B),rt(O,K,A),rt(O,J,B)])
 else:vf=more(vf,[],[[O,A],[O,B],[O,C]])
 checks=[equal((O,H),(O,K),(O,J)),perp(O,H,A,B),perp(O,K,A,C),perp(O,J,B,C)] if incircle else [equal((O,A),(O,B),(O,C))]
 return v0,v1,vf,checks,{v:k for k,v in names.items()}
for n,inc in [(364,False),(365,True)]:
 p={};families=[centered_triangle(p,k,h,inc) for k,h in [('u',1),('r',2),('a',3)]];v0,v1,vf,checks,labels=families[0];allchecks=sum([f[3] for f in families],[]);alllabels={k:v for f in families for k,v in f[4].items()}
 rows=[row('Как начать построение для тупоугольного треугольника?',('Построим биссектрисы двух его углов.' if inc else 'Построим серединные перпендикуляры к двум сторонам.'),'Определение центра '+('вписанной' if inc else 'описанной')+' окружности',[43]),row('Как выбрать радиус?',('Обозначим пересечение биссектрис O. Опустим перпендикуляры OH,OK,OJ к сторонам; их длины равны. Проведём окружность радиуса OH.' if inc else 'Обозначим пересечение перпендикуляров O. Соединим O с A,B,C и проведём окружность радиуса OA: OA=OB=OC.'),'Теорема о '+('вписанной' if inc else 'описанной')+' окружности',[43]),row('Что получится в прямоугольном случае?','Повторим то же построение для прямоугольного треугольника. '+('Центр вписанной окружности остаётся внутри треугольника.' if inc else 'Центр описанной окружности находится на гипотенузе, в её середине.'),'Тот же способ построения; '+('внутренние биссектрисы' if inc else 'свойство окружности с диаметром'),[43,41]),row('Что получится в остроугольном случае?','Повторим построение для остроугольного треугольника. '+('Во всех трёх случаях центр вписанной окружности внутри: это пересечение внутренних биссектрис.' if inc else 'Центр находится внутри. Итак, для тупоугольного треугольника центр снаружи, для прямоугольного — на гипотенузе, для остроугольного — внутри. Построенные примеры показывают эти три положения.'),'Построение центра и сравнение его положения с треугольником',[43])]
 add(n,'single','Начертите тупоугольный, прямоугольный и остроугольный треугольники. '+('Впишите в каждый окружность.' if inc else 'Для каждого постройте описанную окружность.')+' Как расположен её центр относительно треугольника?', 'Во всех трёх случаях внутри.' if inc else 'Тупоугольный: снаружи; прямоугольный: середина гипотенузы; остроугольный: внутри.',rows,p,v0,[v1,vf,families[1][2],families[2][2]],checks=allchecks,cases=[case(vf,'Тупоугольный треугольник',2),case(families[1][2],'Прямоугольный треугольник',3),case(families[2][2],'Остроугольный треугольник',4)],labels=alllabels,offsets={**{k+'A':[-5,-4] for k in 'ura'},**{k+'B':[5,-4] for k in 'ura'},**{k+'C':[0,6] for k in 'ura'}})

