add(368,'single','Какие треугольники ABC, CED, LMN и CTS на рисунке 170 описаны около окружности? Кандидаты показаны раздельно.','ABC и LMN.',[row('Что требуется для описанного треугольника?','Окружность должна касаться всех трёх сторон треугольника: именно отрезков сторон, а не только их продолжений. У ABC это выполнено.','Определение описанного треугольника',[43]),row('Почему CED не подходит?','Окружность находится вне CED. Две прямые его сторон касаются окружности лишь на продолжениях сторон; этого недостаточно.','Касание стороны требует точки касания на отрезке',[43]),row('Что можно сказать о LMN?','Все три стороны LMN касаются окружности в точках этих сторон, а окружность лежит внутри. Поэтому LMN описан около неё.','Определение',[43]),row('Почему CTS не подходит?','S и T — разные точки окружности. Сторона ST — хорда, а не касательная: она имеет с окружностью две общие точки. Поэтому CTS не описан.','Хорда и касательная',[41,42])],p,views[0],views,checks=check+[equal(('_O','S'),('_O','T'),('_O','_R')),col('B','T','D','C'),col('A','S','E','C'),col('M','D','E','N')],cases=[case(v,'Кандидат '+s,0) for v,s in zip(views[1:],['CED','LMN','CTS'])],notes=['Геометрическая модель заново строит касательные и сохраняет принадлежность точек и сторон рис.170.'])

