for prefix,coords in [('o',{'A':[-4,0],'B':[-2,0],'C':[-3,2]}),('i',{'A':[-2,0],'B':[3,0],'C':[-1,3]})]:
 q=deepcopy(coords);q.update(L=[0,-1],R=[0,4])
 for x in 'ABC':q[x+'1']=[-q[x][0],q[x][1]];q['H'+x]=[0,q[x][1]]
 p.update({prefix+k:v for k,v in q.items()});labels378.update({prefix+x:x for x in 'ABC'});labels378.update({prefix+x+'1':x+'₁' for x in 'ABC'})
 A,B,C,L,R=[prefix+x for x in ['A','B','C','L','R']];v0=sc([A,B,C],tri(A,B,C),lines=[[L,R]]);v1=more(v0,[prefix+x+'1' for x in 'ABC'],[[prefix+x,prefix+x+'1'] for x in 'ABC']);vf=sc([prefix+x+s for s in ['', '1'] for x in 'ABC'],tri(A,B,C)+tri(A+'1',B+'1',C+'1'),lines=[[L,R]])
 fv.append((v0,v1,vf));checks378 += [equal((A,B),(A+'1',B+'1')),equal((B,C),(B+'1',C+'1')),equal((C,A),(C+'1',A+'1'))]
 for x in 'ABC':checks378+=symchecks(prefix+x,L,R,prefix+x+'1',prefix+'H'+x)
add(378,'single','Начертите ABC и прямую p, не пересекающую его стороны. Постройте симметричный A₁B₁C₁. Линейкой и транспортиром сравните соответствующие стороны и углы. Повторите для p, пересекающей две стороны ABC.','Симметричные треугольники имеют попарно равные стороны и углы в обоих случаях.',[row('Как отразить треугольник, лежащий по одну сторону p?','Для каждой вершины построим перпендикуляр к p и отложим на нём по другую сторону оси равное расстояние. Получим A₁,B₁,C₁.','Построение симметричной точки',[44]),row('Как закончить и проверить построение?','Соединим A₁B₁,B₁C₁,C₁A₁. Измерим стороны и углы обоих треугольников. Запишем три пары равных длин и три пары равных углов с учётом точности измерений.','Практическая проверка линейкой и транспортиром',[7,10]),row('Что меняется, когда p пересекает треугольник?','Возьмём ось, пересекающую две стороны, и тем же способом отразим все три вершины. Соединим их образы. Часть отрезков двух треугольников может пересекаться, но правило построения то же.','Определение осевой симметрии',[45]),row('Почему равенство не зависит от измерений?','Симметрия сохраняет расстояния, поэтому три стороны соответствующих треугольников равны. По третьему признаку треугольники равны, а значит равны и соответствующие углы.','Сохранение расстояний и третий признак',[45,20])],p,fv[0][0],[fv[0][1],fv[0][2],fv[1][2],fv[1][2]],checks=checks378,cases=[case(fv[1][0],'Ось пересекает две стороны: данные',0),case(fv[1][2],'Ось пересекает две стороны: результат',3)],labels=labels378)
# Shared geometry constructors create distinct configurations for every card.
def axis_example(kind):
 if kind=='segment':
  p={'A':[-3,0],'B':[3,0],'O':[0,0],'U':[0,3],'V':[0,-3]};v0=sc(['A','B'],[['A','B']]);v1=more(v0,lines=[['A','B']]);vf=more(v0,['O'],lines=[['A','B'],['U','V']],rightAngles=[rt('A','O','U')]);cs=[equal(('A','O'),('O','B')),perp('A','B','U','V')]
 elif kind=='angle':
  p={'O':[0,0],'A':[4,2],'B':[4,-2],'U':[5,0],'V':[-1,0]};v0=sc(['O'],rays=[['O','A'],['O','B']]);vf=more(v0,lines=[['U','V']]);v1=vf;cs=[equal(('O','A'),('O','B')),ang('A','O','U',math.degrees(math.atan(.5))),ang('U','O','B',math.degrees(math.atan(.5)))]
 elif kind=='line':
  p={'A':[-3,0],'B':[3,0],'U':[-1,-2],'V':[-1,2],'P':[2,-2],'Q':[2,2]};v0=sc([],lines=[['A','B']]);v1=v0;vf=more(v0,lines=[['A','B'],['U','V'],['P','Q']],note='Показаны две из бесконечного множества поперечных осей; сама исходная прямая тоже ось.');cs=[perp('A','B','U','V'),perp('A','B','P','Q')]
 elif kind=='ray':
  p={'O':[0,0],'A':[4,0]};v0=sc(['O'],rays=[['O','A']]);vf=more(v0,lines=[['O','A']]);v1=vf;cs=[col('O','A')]
 elif kind=='circle':
  p={'O':[0,0],'A':[2,0],'B':[-2,0],'U':[0,2],'V':[0,-2],'P':[math.sqrt(2),math.sqrt(2)],'Q':[-math.sqrt(2),-math.sqrt(2)]};v0=sc(['O'],circles=[circle('O','A')]);vf=more(v0,lines=[['A','B'],['U','V'],['P','Q']]);v1=vf;cs=[equal(('O','A'),('O','B'),('O','U'),('O','V'),('O','P'),('O','Q'))]
 else:
  p={'A':[0,3 if kind=='iso' else 2*math.sqrt(3)],'B':[-2,0],'C':[2,0],'M':[0,0]}
  if kind=='scalene':p['A']=[-.7,2.6]
  p['N']=mid(p['A'],p['C']);p['P']=mid(p['A'],p['B']);v0=sc(['A','B','C'],tri());v1=v0;cs=[]
  if kind=='scalene':vf=v0
  else:
   v0['equalSegments']=[eq('A','B'),eq('A','C')]+([eq('B','C')] if kind=='equilateral' else []);vf=more(v0,['M'],lines=[['A','M']],rightAngles=[rt('A','M','C')]);v1=vf;cs=[equal(('A','B'),('A','C')),equal(('B','M'),('M','C')),perp('A','M','B','C')]
   if kind=='equilateral':vf=more(vf,['N','P'],lines=[['A','M'],['B','N'],['C','P']]);cs+=[equal(('A','B'),('B','C')),perp('B','N','A','C'),perp('C','P','A','B')]
 return p,v0,v1,vf,cs

#379: every printed letter is a separate card.
for part,kind,title,answer,rows in [
('а','segment','отрезок AB','Две оси: прямая AB и серединный перпендикуляр к AB.',[row('Какая ось фиксирует все точки?','Прямая AB является осью: любая точка отрезка принадлежит ей и остаётся на месте.','Точки оси симметричны самим себе',[44]),row('Какая ось меняет концы местами?','Построим середину O и перпендикуляр к AB через неё. При отражении A и B меняются местами, а весь отрезок переходит в себя.','Определение осевой симметрии',[44,45]),row('Почему других осей нет?','Ось либо фиксирует оба конца — тогда это AB, либо меняет их местами — тогда это серединный перпендикуляр. Других возможностей для двух концов нет.','Отражение сохраняет отрезок и его концы',[45])]),
('б','angle','угол hk','Для неразвёрнутого угла — прямая его биссектрисы.',[row('Как построить ось?','Построим биссектрису данного неразвёрнутого угла и продолжим её до прямой.','Построение биссектрисы',[23]),row('Почему это ось?','Отражение относительно этой прямой меняет стороны угла местами: они образуют с ней равные углы. Вершина остаётся на оси.','Определение симметричной фигуры',[44]),row('Как учесть развёрнутый случай?','У неразвёрнутого угла эта ось единственна. Если стороны — противоположные лучи, их объединение является прямой; тогда осей бесконечно много, как у прямой.','Различие неразвёрнутого и развёрнутого угла',[44])]),
('в','iso','равнобедренный треугольник','У неравностороннего — одна ось через вершину и середину основания; у равностороннего — три.',[row('Как провести ось к основанию?','Построим середину M основания BC и прямую AM. В равнобедренном треугольнике AM⊥BC.','Медиана к основанию является высотой',[18]),row('Почему треугольник переходит в себя?','A фиксируется, B и C меняются местами, поэтому стороны AB и AC переходят друг в друга, а BC — в себя.','Определение симметрии',[44,45]),row('Может ли осей быть больше?','Если боковая сторона отличается от основания, вершина A единственна по своему углу, и другая ось невозможна. Если все стороны равны, получаем равносторонний треугольник с тремя осями.','Осевая симметрия сохраняет стороны и углы',[44,45])]),
('г','scalene','разносторонний треугольник','Осей симметрии нет.',[row('Что отражение должно делать с вершинами?','Оно переставляет три вершины. При отражении хотя бы одна вершина фиксируется, а две другие должны поменяться местами: все три на одной оси лежать не могут.','Отражение дважды возвращает каждую точку',[44,45]),row('К какому противоречию это приводит?','Фиксированная вершина равноудалена от двух переставленных вершин. Значит, две стороны треугольника равны, что противоречит разносторонности. Поэтому оси не существует.','Сохранение расстояний',[45])]),
('д','equilateral','равносторонний треугольник','Три оси — прямые трёх медиан.',[row('Как построить первую ось?','Соединим A с серединой M противоположной стороны. Как в равнобедренном треугольнике, AM — ось симметрии.','Свойство медианы равнобедренного треугольника',[18,44]),row('Как получить остальные?','Повторим построение из B и C. Каждая прямая медианы фиксирует одну вершину и меняет две другие местами.','Все стороны равностороннего треугольника равны',[44]),row('Почему осей ровно три?','Любая ось должна фиксировать одну вершину и менять местами две другие. Для каждой из трёх вершин такая прямая единственна.','Свойство отражения и середины противоположной стороны',[44,45])])]:
 p,v0,v1,vf,cs=axis_example(kind);views=[v1]+[vf]*(len(rows)-1);cases=[];labels={}
 if kind in ('angle','iso'):
  q,z,_,f,cc=axis_example('line' if kind=='angle' else 'equilateral');p.update({'x'+k:v for k,v in q.items()})
  def rename_view(v):
   z=deepcopy(v)
   for key in ['points','segments','lines','rays','dashSegments']:
    if key in z:z[key]=[('x'+x if isinstance(x,str) else ['x'+i for i in x]) for x in z[key]]
   for key in ['equalSegments','rightAngles','angleArcs','circles']:
    for mark in z.get(key,[]):
     for name in ['a','b','vertex','from','to','center','through']:
      if name in mark:mark[name]='x'+mark[name]
   return z
  cases=[case(rename_view(f),'Развёрнутый угол' if kind=='angle' else 'Все стороны равны',3)];labels={f'x{k}':k for k in q}
